/** 唱名表：半音索引 → 唱名 */
const SOLFEGE = ["do", "re", "mi", "fa", "so", "la", "si"];

function solfegeOf(note: string): string {
  const letter = note.charAt(0);
  const sharp = note.includes("#");
  const semitone = ({ C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 } as Record<string, number>)[letter] ?? 0;
  return SOLFEGE[(semitone + (sharp ? 1 : 0)) % 7];
}

