// ── Web Audio 合成引擎 ──
function createPianoEngine() {
  const state: { context: AudioContext | null; master: GainNode | null } = { context: null, master: null };

  const ensureContext = () => {
    if (typeof window === "undefined" || !window.AudioContext) return false;
    if (!state.context) {
      state.context = new window.AudioContext();
      state.master = state.context.createGain();
      state.master.gain.value = 0.32;
      state.master.connect(state.context.destination);
    }
    if (state.context.state === "suspended") void state.context.resume();
    return true;
  };

  /**
   * 弹奏一个音符。多层谐波 + ADSR 包络，包络与谐波层由当前音色决定。
   */
  const playNote = (noteName: string, timbre: TimbreDef, velocity = 0.8) => {
    if (!ensureContext()) return;
    const context = state.context!;
    const master = state.master!;
    const frequency = NOTE_FREQUENCIES[noteName];
    if (!frequency) return;

    const now = context.currentTime;
    const noteGain = context.createGain();
    noteGain.connect(master);

    const { attack, decay, sustain, release } = timbre;
    const totalDuration = attack + decay + release;
    const peakVolume = Math.min(velocity, 0.95);

    noteGain.gain.setValueAtTime(0.0001, now);
    noteGain.gain.exponentialRampToValueAtTime(peakVolume, now + attack);
    noteGain.gain.exponentialRampToValueAtTime(peakVolume * sustain, now + attack + decay);
    noteGain.gain.exponentialRampToValueAtTime(0.0001, now + totalDuration);

    for (const [ratio, type, volume, extraDecay] of timbre.harmonics) {
      const oscillator = context.createOscillator();
      const harmonicGain = context.createGain();
      oscillator.type = type;
      oscillator.frequency.setValueAtTime(frequency * ratio, now);

      const hPeak = volume * peakVolume;
      const hSustain = hPeak * sustain * Math.max(0.08, 1 - extraDecay);
      harmonicGain.gain.setValueAtTime(0.0001, now);
      harmonicGain.gain.exponentialRampToValueAtTime(hPeak, now + attack);
      harmonicGain.gain.exponentialRampToValueAtTime(hSustain, now + attack + decay * (1 + extraDecay * 0.4));
      harmonicGain.gain.exponentialRampToValueAtTime(0.0001, now + totalDuration * Math.max(0.35, 1 - extraDecay * 0.35));

      oscillator.connect(harmonicGain);
      harmonicGain.connect(noteGain);
      oscillator.start(now);
      oscillator.stop(now + totalDuration + 0.05);
    }

    // 失谐层：以 cents 偏移基频，模拟双弦拍频（honky-tonk）
    for (const [cents, type, volume] of timbre.detune ?? []) {
      const oscillator = context.createOscillator();
      const detuneGain = context.createGain();
      oscillator.type = type;
      oscillator.frequency.setValueAtTime(frequency, now);
      oscillator.detune.setValueAtTime(cents, now);

      const dPeak = volume * peakVolume;
      const dSustain = dPeak * sustain;
      detuneGain.gain.setValueAtTime(0.0001, now);
      detuneGain.gain.exponentialRampToValueAtTime(dPeak, now + attack);
      detuneGain.gain.exponentialRampToValueAtTime(dSustain, now + attack + decay);
      detuneGain.gain.exponentialRampToValueAtTime(0.0001, now + totalDuration);

      oscillator.connect(detuneGain);
      detuneGain.connect(noteGain);
      oscillator.start(now);
      oscillator.stop(now + totalDuration + 0.05);
    }
  };

  const setVolume = (value: number) => {
    if (state.master && state.context) {
      const now = state.context.currentTime;
      state.master.gain.cancelScheduledValues(now);
      state.master.gain.setValueAtTime(state.master.gain.value, now);
      state.master.gain.linearRampToValueAtTime(value, now + 0.06);
    }
  };

  const dispose = () => {
    if (state.context) { void state.context.close(); state.context = null; state.master = null; }
  };

  return { playNote, setVolume, dispose, ensureContext };
}

export function PianoPage() {
  const { t } = useTranslation();
  usePreferences(); // 订阅偏好以触发 data-motion/data-theme 属性更新
  const engineRef = useRef<ReturnType<typeof createPianoEngine> | null>(null);
  if (!engineRef.current) engineRef.current = createPianoEngine();

  const [activeNotes, setActiveNotes] = useState<Set<string>>(new Set());
  const [muted, setMuted] = useState(false);
  const [volume, setVolume] = useState(0.5);
  const [lastNote, setLastNote] = useState("");
  const [timbreId, setTimbreId] = useState("grand");
  const [layoutId, setLayoutId] = useState("standard");
  const [tab, setTab] = useState<"sound" | "keys">("sound");
  const [showHints, setShowHints] = useState(true);
  const [showSolfege, setShowSolfege] = useState(true);
  const activeKeysRef = useRef<Set<string>>(new Set());
  const noteTimersRef = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map());

  const timbre = TIMBRES.find((item) => item.id === timbreId) ?? TIMBRES[0];
  const layout = KEY_LAYOUTS.find((item) => item.id === layoutId) ?? KEY_LAYOUTS[0];

  // 清理引擎和音符释放定时器
  useEffect(() => {
    const engine = engineRef.current;
    return () => {
      engine?.dispose();
      for (const timer of noteTimersRef.current.values()) clearTimeout(timer);
      noteTimersRef.current.clear();
    };
  }, []);

  // 音量同步：滑块 0-1 → 主增益 0-0.64，静音时归零
  useEffect(() => {
    engineRef.current?.setVolume(muted ? 0 : volume * 0.64);
  }, [muted, volume]);

  const triggerNote = useCallback((note: string) => {
    if (muted) return;
    engineRef.current?.playNote(note, timbre);
    setLastNote(note);
    setActiveNotes((prev) => {
      const next = new Set(prev);
      next.add(note);
      return next;
    });
    // 清除该音符之前的释放定时器，避免快速连击时累积回调
    const prevTimer = noteTimersRef.current.get(note);
    if (prevTimer) clearTimeout(prevTimer);
    // 视觉反馈持续 220ms
    noteTimersRef.current.set(note, setTimeout(() => {
      setActiveNotes((prev) => {
        const next = new Set(prev);
        next.delete(note);
        return next;
      });
      noteTimersRef.current.delete(note);
    }, 220));
  }, [muted, timbre]);

  // 键盘事件（使用当前键位方案）
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.repeat || event.ctrlKey || event.metaKey || event.altKey) return;
      const key = event.key.toLowerCase();
      const note = layout.map[key];
      if (note && !activeKeysRef.current.has(key)) {
        activeKeysRef.current.add(key);
        triggerNote(note);
      }
    };
    const handleKeyUp = (event: KeyboardEvent) => {
      activeKeysRef.current.delete(event.key.toLowerCase());
    };
    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keyup", handleKeyUp);
    };
  }, [triggerNote, layout]);

  // 反向映射：音符 → 键字符（用于琴键提示）
  const noteToKey = new Map<string, string>();
  for (const [key, note] of Object.entries(layout.map)) {
    if (!noteToKey.has(note)) noteToKey.set(note, PHYSICAL_LABELS[key] ?? key.toUpperCase());
  }

  // 构建白键/黑键布局
  const whiteKeys = PIANO_KEYS.filter((k) => !k.black);
  const blackKeyPositions = PIANO_KEYS
    .map((key, index) => ({ ...key, index }))
    .filter((k) => k.black)
    .map((bk) => {
      // 找到该黑键前面的白键索引
      const precedingWhiteCount = PIANO_KEYS.slice(0, bk.index).filter((k) => !k.black).length;
      return { ...bk, afterWhiteIndex: precedingWhiteCount };
    });

  return (
    <>
      <SeoHead titleKey="seo.pianoTitle" descriptionKey="seo.pianoDescription" path="piano" />
      <main className="piano-page">
        {/* 背景装饰 */}
      <div className="piano-atmosphere" aria-hidden="true">
        <div className="piano-atmosphere__orb piano-atmosphere__orb--a" />
        <div className="piano-atmosphere__orb piano-atmosphere__orb--b" />
        <div className="piano-atmosphere__orb piano-atmosphere__orb--c" />
      </div>

      {/* 顶栏 */}
      <header className="piano-topbar">
        <Link className="piano-brand" to="/">
          <img src="./branding/hongyunx-mark.svg" alt="" loading="lazy" decoding="async" />
          <span><strong>{t("brand.name")}</strong><small>PIANO STUDIO</small></span>
        </Link>
        <div className="piano-topbar__actions">
          <SettingsControls />
          <Link className="piano-exit" to="/"><ArrowLeft size={14} />{t("piano.exit")}</Link>
        </div>
      </header>

      {/* 状态栏：品牌花体 + 当前音符 + 音色 + 键位 + 音量条 */}
      <div className="piano-statusbar">
        <span className="piano-statusbar__script">{t("piano.scriptBrand")}</span>
        <span className="piano-statusbar__note">{lastNote || "--"}</span>
        <span className="piano-statusbar__divider" aria-hidden="true" />
        <Piano size={14} className="piano-statusbar__icon" aria-hidden="true" />
        <span className="piano-statusbar__meta">{t(timbre.nameKey)}</span>
        <span className="piano-statusbar__divider" aria-hidden="true" />
        <Keyboard size={14} className="piano-statusbar__icon" aria-hidden="true" />
        <span className="piano-statusbar__meta">{t(layout.nameKey)}</span>
        <span className="piano-statusbar__track" aria-hidden="true"><i style={{ width: `${Math.round(volume * 100)}%` }} /></span>
      </div>

      {/* 全宽钢琴键盘 */}
      <div className="piano-keyboard-wrap">
        <div className="piano-keyboard" role="group" aria-label={t("piano.keyboardLabel")}>
          {/* 白键 */}
          {whiteKeys.map((key) => (
            <button
              key={key.note}
              className={`piano-key piano-key--white ${activeNotes.has(key.note) ? "piano-key--active" : ""}`}
              type="button"
              onPointerDown={() => triggerNote(key.note)}
              aria-label={key.note}
            >
              <span className="piano-key__hint">{showHints ? noteToKey.get(key.note) ?? "" : ""}</span>
              <span className="piano-key__solfege">{showSolfege ? solfegeOf(key.note) : ""}</span>
              <span className="piano-key__label">{key.label}</span>
            </button>
          ))}
          {/* 黑键 */}
          {blackKeyPositions.map((bk) => (
            <button
              key={bk.note}
              className={`piano-key piano-key--black ${activeNotes.has(bk.note) ? "piano-key--active" : ""}`}
              style={{ left: `calc(${bk.afterWhiteIndex} * var(--piano-white-width) + var(--piano-white-width) * 0.62)` }}
              type="button"
              onPointerDown={() => triggerNote(bk.note)}
              aria-label={bk.note}
            >
              {showHints ? <span className="piano-key__hint">{noteToKey.get(bk.note) ?? ""}</span> : null}
            </button>
          ))}
        </div>
      </div>

      {/* 控制台：标签页切换 */}
      <div className="piano-console">
        <div className="piano-tabs" role="tablist" aria-label={t("piano.consoleLabel")}>
          <button
            className={`piano-tab ${tab === "sound" ? "piano-tab--active" : ""}`}
            type="button"
            role="tab"
            aria-selected={tab === "sound"}
            onClick={() => setTab("sound")}
          >
            <SlidersHorizontal size={15} />{t("piano.tabSound")}
          </button>
          <button
            className={`piano-tab ${tab === "keys" ? "piano-tab--active" : ""}`}
            type="button"
            role="tab"
            aria-selected={tab === "keys"}
            onClick={() => setTab("keys")}
          >
            <Keyboard size={15} />{t("piano.tabKeys")}
          </button>
          <button
            className={`piano-mute ${muted ? "piano-mute--muted" : ""}`}
            type="button"
            onClick={() => setMuted((v) => !v)}
            title={t(muted ? "piano.unmute" : "piano.mute")}
            aria-label={t(muted ? "piano.unmute" : "piano.mute")}
            aria-pressed={!muted}
          >
            {muted ? <VolumeX size={15} /> : <Volume2 size={15} />}
            <span>{t(muted ? "piano.muted" : "piano.soundOn")}</span>
          </button>
        </div>

        {tab === "sound" ? (
          <div className="piano-panel">
            <div className="piano-panel__section">
              <div className="piano-panel__heading"><b>1</b><span>{t("piano.instrumentLabel")}</span></div>
              <div className="piano-timbre-grid">
                {TIMBRES.map((item) => (
                  <button
                    key={item.id}
                    className={`piano-timbre ${item.id === timbreId ? "piano-timbre--active" : ""}`}
                    type="button"
                    onClick={() => setTimbreId(item.id)}
                    aria-pressed={item.id === timbreId}
                  >
                    {item.thumb && <img className="piano-timbre__thumb" src={item.thumb} alt="" aria-hidden="true" loading="lazy" decoding="async" />}
                    <span className="piano-timbre__body">
                      <span className="piano-timbre__name-row">
                        <strong>{t(item.nameKey)}</strong>
                        {item.sampled && <span className="piano-timbre__badge" aria-label="Sampled instrument">MP3</span>}
                      </span>
                      <small>{t(item.enKey)}</small>
                    </span>
                  </button>
                ))}
              </div>
            </div>
            <div className="piano-panel__section">
              <div className="piano-panel__heading"><b>2</b><span>{t("piano.volumeLabel")}</span></div>
              <div className="piano-volume">
                <VolumeX size={15} aria-hidden="true" />
                <input
                  className="piano-volume__slider"
                  type="range"
                  min={0}
                  max={1}
                  step={0.01}
                  value={volume}
                  onChange={(event) => setVolume(Number(event.target.value))}
                  aria-label={t("piano.volumeLabel")}
                />
                <Volume2 size={15} aria-hidden="true" />
                <output className="piano-volume__value">{volume.toFixed(2)}</output>
              </div>
            </div>
          </div>
        ) : (
          <div className="piano-panel">
            <div className="piano-panel__section">
              <div className="piano-panel__heading"><b>1</b><span>{t("piano.layoutLabel")}</span></div>
              <div className="piano-layout-row">
                {KEY_LAYOUTS.map((item) => (
                  <button
                    key={item.id}
                    className={`piano-layout-chip ${item.id === layoutId ? "piano-layout-chip--active" : ""}`}
                    type="button"
                    onClick={() => setLayoutId(item.id)}
                    aria-pressed={item.id === layoutId}
                  >
                    <Keyboard size={13} />{t(item.nameKey)}
                  </button>
                ))}
              </div>
              <div className="piano-layout-desc"><p>{t(layout.descKey)}</p></div>
            </div>
            <div className="piano-panel__section">
              <div className="piano-panel__heading"><b>2</b><span>{t("piano.keyboardLabel")}</span></div>
              <div className="piano-toggle-row">
                <label className="piano-toggle">
                  <input type="checkbox" checked={showHints} onChange={(event) => setShowHints(event.target.checked)} />
                  <i aria-hidden="true" />
                  <span>{t("piano.showHints")}</span>
                </label>
                <label className="piano-toggle">
                  <input type="checkbox" checked={showSolfege} onChange={(event) => setShowSolfege(event.target.checked)} />
                  <i aria-hidden="true" />
                  <span>{t("piano.showSolfege")}</span>
                </label>
              </div>
              <div className="piano-keymap" aria-hidden="true">
                {PHYSICAL_ROWS.map((row, rowIndex) => (
                  <div className="piano-keymap__row" key={rowIndex}>
                    {row.map((physKey) => {
                      const note = layout.map[physKey];
                      return (
                        <span key={physKey} className={`piano-keymap__key ${note ? "piano-keymap__key--mapped" : ""}`}>
                          <em>{PHYSICAL_LABELS[physKey] ?? physKey.toUpperCase()}</em>
                          {note ? <b>{note}</b> : null}
                        </span>
                      );
                    })}
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

        {/* 技术说明 */}
        <div className="piano-tech-note">
          <p>{t("piano.techNote")}</p>
        </div>
      </main>
    </>
  );
}
